define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_67.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e225147","topics":[]},{"title":"Preparing the workstation for a computer replacement","shortdesc":"<p class=\"shortdesc\">Prepare the workstation so all data is saved prior to shutting down and replacing the host computer in the Global Operator Cabinet (GOC).<\/p>","href":"t_PreparingTheWorkstationForAComputerReplacement_5.html","attributes":{"data-id":"id_2007196"},"menu":{"hasChildren":false},"tocID":"id_2007196-d46e225251","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_72.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e225355","topics":[]},{"title":"Applying LOTO - Global Operator Cabinet (GOC) and operator workspace","shortdesc":"<p class=\"shortdesc\">Apply LOTO before servicing the GOC or items in the operator workspace. Applying LOTO makes sure the environment is safe when working on these items.<\/p>","href":"t_Applying-LOTO-GOCandOWLOTO-Premier_12.html","attributes":{"data-id":"id_2001924"},"menu":{"hasChildren":false},"tocID":"id_2001924-d46e225459","topics":[]},{"title":"Removing the DVD drive - Dell T5820","shortdesc":"<p class=\"shortdesc\">Remove the DVD drive from the host computer.<\/p>","href":"t_RemovingTheDVDDrive-DellT5820.html","attributes":{"data-id":"id_2015016"},"menu":{"hasChildren":false},"tocID":"id_2015016-d46e225563","topics":[]},{"title":"Installing the DVD drive - Dell T5820","shortdesc":"<p class=\"shortdesc\">Install the DVD drive in the host computer.<\/p>","href":"t_InstallingTheDVDDrive-DellT5820.html","attributes":{"data-id":"id_2015017"},"menu":{"hasChildren":false},"tocID":"id_2015017-d46e225667","topics":[]},{"title":"Removing LOTO - Global Operator Cabinet (GOC) and operator workspace","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the GOC and operator workspace before restoring power to these items.<\/p>","href":"t_Removing-LOTO-GOCandOW-Premier_12.html","attributes":{"data-id":"id_2001925"},"menu":{"hasChildren":false},"tocID":"id_2001925-d46e225771","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_71.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e225875","topics":[]},{"title":"Finalizing DVD drive replacement on the host computer","shortdesc":"<p class=\"shortdesc\">Follow this procedure to finalize a DVD drive replacement.<\/p>","href":"t_FinalizingDVDDriveReplacement_2.html","attributes":{"data-id":"id_2007452"},"menu":{"hasChildren":false},"tocID":"id_2007452-d46e225979","topics":[]}]});